        while(left<right){
            if(alice<plants[left]){
                ++answer;
                alice=capacityA;
            }
            alice-=plants[left++];
            if(bob<plants[right]){
                ++answer;
                bob=capacityB;
            }
            bob-=plants[right--];
        }
        if(left==right&&max(alice,bob)<plants[left])++answer;
        return answer;
    }
